import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Typed decisions — Verdict, and Laya as the embedded open-source decision model","description":"","frontmatter":{},"headers":[],"relativePath":"components/decisions.md","filePath":"components/decisions.md"}`),a={name:`components/decisions.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="typed-decisions-—-verdict-and-laya-as-the-embedded-open-source-decision-model" tabindex="-1">Typed decisions — Verdict, and Laya as the embedded open-source decision model <a class="header-anchor" href="#typed-decisions-—-verdict-and-laya-as-the-embedded-open-source-decision-model" aria-label="Permalink to “Typed decisions — Verdict, and Laya as the embedded open-source decision model”">​</a></h1><h2 id="why-a-decision-engine" tabindex="-1">Why a decision engine <a class="header-anchor" href="#why-a-decision-engine" aria-label="Permalink to “Why a decision engine”">​</a></h2><p>An agent makes thousands of judgements that are not prose: which domain handles this message, is this reply a plain yes, which of these options did the user mean, is it safe to call the write tool, how severe is this report. Answering them with a generative model is slow, expensive, verbose and uncalibrated — and routing them through prompt rules is unreliable.</p><p>A <strong>typed decision</strong> is a question with a fixed answer shape, answered with a probability distribution:</p><table tabindex="0"><thead><tr><th>type</th><th>question</th><th>answer</th></tr></thead><tbody><tr><td><code>choice</code></td><td>pick one of named options (<code>criteria: {key: description}</code>)</td><td><code>choice</code>, <code>probabilities</code>, <code>confidence</code></td></tr><tr><td><code>noul</code></td><td>is this statement true?</td><td><code>noul</code> = P(true), <code>confidence</code> = |2p−1|</td></tr><tr><td><code>score</code></td><td>which ordinal level? (<code>criteria: [levels]</code>)</td><td><code>score</code> (expected level), <code>level</code>, <code>probabilities</code>, <code>confidence</code></td></tr></tbody></table><p>This is the System One protocol (<code>POST /v1/systemone {state, questions}</code>), spoken by the proprietary Jev API and by <strong>Laya</strong>, an open-weight, Apache-2.0 decision model from Convai Innovations (github.com/NandhaKishorM/laya): ModernBERT-large / mmBERT-base encoders that answer in a single forward pass (~30 ms per question on a GPU, 100+ languages in the multilingual checkpoint, a <code>laya-typed-decisions</code> checkpoint fine-tuned for agent workflows).</p><h2 id="what-marg-adk-verdict-gives-you" tabindex="-1">What @marg-adk/verdict gives you <a class="header-anchor" href="#what-marg-adk-verdict-gives-you" aria-label="Permalink to “What @marg-adk/verdict gives you”">​</a></h2><ul><li><strong>Backends behind one interface</strong>: <code>rulesBackend</code> (regex / predicates — free, certain, first), <code>systemOneBackend</code> (Laya via Ollama or <code>laya-serve</code>, or any compatible server), <code>llmBackend</code> (a generative model answering one letter, with logprobs → a real distribution; a bare letter → an honest low-confidence one-hot), <code>mockBackend</code> (tests).</li><li><strong>A cascade</strong>: each question travels down the chain until answered with confidence ≥ the threshold; a dead link is skipped and counted; low-confidence earlier answers survive as a flagged fallback; <code>answered_by</code> says who answered what.</li><li><strong>A Decider</strong> facade: <code>choose</code>, <code>yesNo</code>, <code>score</code>, <code>decide</code>, <code>decideSchema</code> (a JSON-schema-like object with enums / booleans / bounded integers → values), per-question calibration and abstention (<code>min_confidence</code> → <code>low_confidence</code>, <code>abstained</code>).</li><li><strong>Calibration maths</strong>: temperature scaling with a grid-search fit, accuracy / Brier / ECE and the abstention trade-off table, <code>fitAbstentionThreshold(samples, targetPrecision)</code>.</li><li><strong>A System One server</strong> (<code>createSystemOneServer(backend)</code>): serve ANY backend over the same protocol — tests, air-gapped deployments, a gradual migration from a hosted API.</li><li><strong>A CLI</strong> (<code>npm run verdict -- &quot;&lt;text&gt;&quot; --choice dept=a,b,c</code>) and an <strong>MCP server</strong> (<code>npm run verdict:mcp</code>) for any agent that speaks MCP.</li></ul><p>Inside the runtime, the router asks a <code>choice</code> over the domain cards (keywords first, then the decision model, then the LLM with logprobs), sticky to the active domain.</p><h2 id="running-laya" tabindex="-1">Running Laya <a class="header-anchor" href="#running-laya" aria-label="Permalink to “Running Laya”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Ollama (≥ 0.40.0):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laya</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">                      # or laya:421m-typed-decisions-mlx-fp16 / laya:322m-multilingual-mlx-fp16</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VERDICT_SYSTEMONE_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:11434 VERDICT_SYSTEMONE_MODEL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">laya</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># or the Python server:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;laya[serve]&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAYA_PORT</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8000</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> laya-serve</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">             # POST /v1/systemone, /v1/systemone/batch, GET /models</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VERDICT_SYSTEMONE_URL</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:8000</span></span></code></pre></div><p><code>docker compose -f deploy/docker-compose.yml --profile decisions up -d</code> starts an Ollama service and pulls the model.</p><p>Limits to design around: <code>choice</code> / <code>score</code> take 2–26 options (about 20 recommended — the published Banking77 score of 0.43 on 77 options is the reason); each question has a ~512-token budget shared by instructions, options and state (1024 on the typed-decisions and multilingual checkpoints); request bodies up to 64 KiB; batch up to 64 states. Published figures (the authors&#39; own measurements, T4 GPU): typed-decisions benchmark 0.766 vs 0.727 for the hosted API, ECE 0.081, ~33 ms per question. Verify on your data.</p><h2 id="calibrate-before-you-trust-a-threshold" tabindex="-1">Calibrate before you trust a threshold <a class="header-anchor" href="#calibrate-before-you-trust-a-threshold" aria-label="Permalink to “Calibrate before you trust a threshold”">​</a></h2><p>Confidence is a property of the distribution, not the chance of being right. Build a labelled set from your own traffic (a few hundred decisions), run <code>evaluate()</code>, fit a temperature, choose the threshold that reaches the precision you need, and store it per question id in the Decider&#39;s <code>calibration</code>. Re-run when the model, the options or the traffic change.</p><h2 id="where-not-to-use-it" tabindex="-1">Where NOT to use it <a class="header-anchor" href="#where-not-to-use-it" aria-label="Permalink to “Where NOT to use it”">​</a></h2><p>The create gate reads a yes by its whole content with rules only. A decision model may advise a reader on the model-handoff path; it must never loosen a gate where a false yes performs a write. The cascade&#39;s <code>maxDepth</code> exists for exactly this.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/DECISIONS.md">docs/DECISIONS.md</a> — edit it there; the site mirrors the repository.</small></p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};